fn select(&self, frontier: &AVLTreeSetMtPer<V>) -> (selected: (AVLTreeSetMtPer<V>, bool))
    requires
        obeys_feq_clone::<V>(),
        frontier.spec_avltreesetmtper_wf(),
        frontier@.len() < usize::MAX as nat,
    ensures selected.0@.subset_of(frontier@);

